<script setup lang="ts">
import Modal from "@papilio/ui/Modal.vue";
import { computed, onMounted, ref, watch, toRaw } from "vue";
import { useRoute } from "vue-router";
import { useAuth } from "@papilio/auth";
import { item, request, query, type Page, type Plan, type Reseller, type ResellerPlan, type ResellerPlanChange, type AgreementPrice } from "@papilio/api";
import { faNumber,toman } from "@papilio/ui";
import NumField from "@papilio/ui/NumField.vue";
import AgreementPriceEditor from "../components/AgreementPriceEditor.vue";
import { useI18n } from "vue-i18n";
import { useLocalizedFormats } from "../composables/useLocalizedFormats";
const {t}=useI18n(),{date}=useLocalizedFormats();
const route=useRoute(),auth=useAuth(),admin=computed(()=>!route.meta.reseller);
const parent=ref<Reseller|null>(null), rows=ref<ResellerPlan[]>([]), selected=ref<ResellerPlan|null>(null), draft=ref<AgreementPrice|null>(null),enabled=ref(false),reason=ref("");
const page=ref(1),pages=ref(1),total=ref(0),q=ref(""),loading=ref(false),busy=ref(false),error=ref(""),notice=ref("");
const base=computed(()=>admin.value?`/v1/admin/resellers/${parent.value?.id}/plans`:"/v1/reseller/plans");
const canManage=computed(()=>admin.value&&auth.can("resellers","manage"));
const plans=ref<Plan[]>([]),planPage=ref(1),planPages=ref(1),planTotal=ref(0),planQ=ref(""),planLoading=ref(false),planError=ref(""),chosen=ref<Plan|null>(null);
const newMode=ref<""|AgreementPrice["mode"]>(""),newRounding=ref<""|AgreementPrice["rounding"]>(""),newQuantum=ref(""),newFixed=ref(""),newDiscount=ref(""),newEnabled=ref<""|"true"|"false">(""),newReason=ref("");
const history=ref<ResellerPlanChange[]>([]),historyPage=ref(1),historyPages=ref(1),historyTotal=ref(0),historyLoading=ref(false),historyError=ref("");
let listVersion=0,selectionVersion=0,planVersion=0,historyVersion=0;
async function start():Promise<void>{error.value="";if(admin.value){try{parent.value=await item<Reseller>(`/v1/admin/resellers/${Number(route.params.resellerId)}`);}catch(cause){error.value=cause instanceof Error?cause.message:t("resellerPlans.operationFailed");return;}}await load();}
async function load():Promise<void>{if(admin.value&&!parent.value)return;const version=++listVersion;loading.value=true;error.value="";try{const result=await request<Page<ResellerPlan>>(`${base.value}?${query({page:page.value,q:q.value})}`);if(version!==listVersion)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;}catch(cause){if(version===listVersion)error.value=cause instanceof Error?cause.message:t("resellerPlans.operationFailed");}finally{if(version===listVersion)loading.value=false;}}
async function loadPlans():Promise<void>{const version=++planVersion;planLoading.value=true;planError.value="";try{const result=await request<Page<Plan>>(`/v1/admin/plans?${query({page:planPage.value,q:planQ.value})}`);if(version!==planVersion)return;plans.value=result.data;planPages.value=result.meta.pager?.total_pages??1;planTotal.value=result.meta.pager?.total_items??0;}catch(cause){if(version===planVersion)planError.value=cause instanceof Error?cause.message:t("resellerPlans.operationFailed");}finally{if(version===planVersion)planLoading.value=false;}}
async function select(row:ResellerPlan,preserve=false):Promise<void>{if(busy.value)return;if(!admin.value){selected.value=row;draft.value=structuredClone(toRaw(row.price));return;}const version=++selectionVersion;error.value="";try{const fresh=await item<ResellerPlan>(`${base.value}/${row.id}`);if(version!==selectionVersion)return;const same=selected.value?.id===row.id;selected.value=fresh;if(!preserve||!same){draft.value=structuredClone(fresh.price);enabled.value=fresh.enabled;reason.value="";}history.value=[];historyPage.value=1;void loadHistory();}catch(cause){if(version===selectionVersion)error.value=cause instanceof Error?cause.message:t("resellerPlans.operationFailed");}}
async function loadHistory():Promise<void>{const row=selected.value;if(!row||!admin.value)return;const version=++historyVersion;historyLoading.value=true;historyError.value="";try{const result=await request<Page<ResellerPlanChange>>(`${base.value}/${row.id}/history?${query({page:historyPage.value})}`);if(version!==historyVersion||selected.value?.id!==row.id)return;history.value=result.data;historyPages.value=result.meta.pager?.total_pages??1;historyTotal.value=result.meta.pager?.total_items??0;}catch(cause){if(version===historyVersion)historyError.value=cause instanceof Error?cause.message:t("resellerPlans.operationFailed");}finally{if(version===historyVersion)historyLoading.value=false;}}
async function save():Promise<void>{const row=selected.value;if(!row||!draft.value||busy.value||!canManage.value)return;busy.value=true;error.value="";notice.value="";try{const fresh=await item<ResellerPlan>(`${base.value}/${row.id}`,"PUT",{expected_revision:row.revision,enabled:enabled.value,price:draft.value,reason:reason.value});selected.value=fresh;draft.value=structuredClone(fresh.price);reason.value="";notice.value=t("resellerPlans.saved");await Promise.all([load(),loadHistory()]);}catch(cause){error.value=cause instanceof Error?cause.message:t("resellerPlans.operationFailed");}finally{busy.value=false;}}
async function create():Promise<void>{if(!chosen.value||!newMode.value||!newRounding.value||newEnabled.value===""||busy.value||!canManage.value)return;busy.value=true;error.value="";notice.value="";try{const pricing:AgreementPrice={mode:newMode.value,rounding:newRounding.value,quantum_rial:Number(newQuantum.value),fixed_price_rial:newMode.value==="fixed"?Number(newFixed.value):null,discount_bps:newMode.value==="discount"?Number(newDiscount.value):null};const row=await item<ResellerPlan>(base.value,"POST",{plan_id:chosen.value.id,enabled:newEnabled.value==="true",price:pricing,reason:newReason.value});selected.value=row;draft.value=structuredClone(toRaw(row.price));enabled.value=row.enabled;reason.value="";chosen.value=null;newMode.value="";newRounding.value="";newQuantum.value="";newFixed.value="";newDiscount.value="";newEnabled.value="";newReason.value="";historyPage.value=1;createOpen.value=false;notice.value=t("resellerPlans.created");await Promise.all([load(),loadHistory()]);}catch(cause){error.value=cause instanceof Error?cause.message:t("resellerPlans.operationFailed");}finally{busy.value=false;}}
watch(q,()=>{page.value=1;void load();});onMounted(()=>void start());
const createOpen=ref(false);
</script>
<template><div class="page-head"><div><p class="eyebrow">{{t("resellerPlans.eyebrow")}}</p><h1>{{t("resellerPlans.title",{name:parent?.title??t("resellerPlans.reseller")})}}</h1><p class="subtitle">{{t("resellerPlans.description")}}</p></div><RouterLink v-if="admin" to="/resellers" class="btn secondary">{{t("resellerPlans.resellers")}}</RouterLink><button class="btn secondary" :disabled="loading||busy" @click="parent||!admin?load():start()">{{t("resellerPlans.refresh")}}</button><button v-if="canManage&&parent" class="btn" :disabled="busy" @click="createOpen=true">+ {{t("resellerPlans.createAgreement")}}</button></div><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p>
<div :class="{split:!!selected}"><section class="card"><div class="card-pad"><label class="field"><span>{{t("resellerPlans.findPlan")}}</span><input v-model="q" maxlength="120"/></label></div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("resellerPlans.plan")}}</th><th>{{t("resellerPlans.quotaDuration")}}</th><th>{{t("resellerPlans.price")}}</th><th>{{t("resellerPlans.status")}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" tabindex="0" :class="{'selected-row':selected?.id===row.id}" @click="select(row)" @keydown.enter="select(row)"><td>{{row.title}}<br/><small dir="ltr">{{row.code}}</small></td><td>{{(row.quota_bytes === null ? t('resellerPlans.unlimited') : faNumber(row.quota_bytes))}} bytes / {{row.duration_days === null ? t('resellerPlans.noExpiry') : faNumber(row.duration_days) + " days"}}</td><td>{{toman(row.price_rial)}}</td><td>{{row.enabled?t('resellerPlans.agreementEnabled'):t('resellerPlans.agreementPaused')}} · {{row.plan_active?t('resellerPlans.planActive'):t('resellerPlans.planInactive')}}</td></tr></tbody></table><p v-if="loading" class="empty">{{t("resellerPlans.loading")}}</p><p v-else-if="!rows.length&&!error" class="empty">{{t("resellerPlans.empty")}}</p></div><div class="pager"><button :disabled="page<=1||loading||busy" @click="page--;load()">‹</button><span>{{faNumber(page)}} · {{faNumber(total)}} {{t("resellerPlans.agreements")}}</span><button :disabled="page>=pages||loading||busy" @click="page++;load()">›</button></div></section>
<div class="stack"><section v-if="selected&&draft" class="card card-pad"><h2>{{selected.title}}</h2><p>{{t("resellerPlans.revision",{revision:faNumber(selected.revision)})}} · {{t("resellerPlans.catalogPrice")}} {{toman(selected.catalog_price_rial)}} · {{t("resellerPlans.agreementPrice")}} {{toman(selected.price_rial)}}</p><form v-if="canManage" class="form-grid" @submit.prevent="save"><label class="check-row"><input v-model="enabled" type="checkbox" :disabled="busy"/>{{t("resellerPlans.agreementEnabled")}}</label><AgreementPriceEditor v-model="draft" :disabled="busy"/><label class="field"><span>{{t("resellerPlans.changeReason")}}</span><input v-model="reason" minlength="3" maxlength="250" required :disabled="busy"/></label><button class="btn" :disabled="busy||reason.trim().length<3">{{t("resellerPlans.save")}}</button></form><AgreementPriceEditor v-else :model-value="selected.price" disabled/><button v-if="admin" class="btn secondary" :disabled="busy" @click="select(selected,true)">{{t("resellerPlans.refreshRetain")}}</button><div v-if="admin"><h3>{{t("resellerPlans.history")}}</h3><p v-if="historyError" class="message error">{{historyError}} <button class="btn secondary" @click="loadHistory">{{t("resellerPlans.retry")}}</button></p><p v-if="historyLoading">{{t("resellerPlans.loading")}}</p><details v-for="change in history" :key="change.id"><summary>{{t("resellerPlans.revision",{revision:faNumber(change.revision)})}} · {{change.reason}}</summary><p>{{t("resellerPlans.staff")}} {{faNumber(change.staff_id)}} · {{date(change.created_at)}} · {{change.enabled?t("resellerPlans.active"):t("resellerPlans.paused")}}</p><AgreementPriceEditor :model-value="change.price" disabled/></details><div class="pager"><button :disabled="historyPage<=1||historyLoading" @click="historyPage--;loadHistory()">‹</button><span>{{faNumber(historyPage)}} · {{faNumber(historyTotal)}} {{t("resellerPlans.changes")}}</span><button :disabled="historyPage>=historyPages||historyLoading" @click="historyPage++;loadHistory()">›</button></div></div></section>
<Modal v-if="canManage&&parent" v-model="createOpen" :title="t('resellerPlans.createAgreement')" :busy="busy" wide><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="!auth.can('catalog')" class="hint-box">{{t("resellerPlans.catalogAccessRequired")}}</p><template v-else><p v-if="chosen">{{t("resellerPlans.selectedPlan")}}: {{chosen.title}} · {{toman(chosen.price_rial)}} <button class="btn small secondary" :disabled="busy" @click="chosen=null">{{t("resellerPlans.clear")}}</button></p><div class="toolbar"><label class="field"><span>{{t("resellerPlans.findDestinationPlan")}}</span><input v-model="planQ" @keydown.enter.prevent="planPage=1;loadPlans()"/></label><button class="btn secondary" :disabled="busy||planLoading" @click="planPage=1;loadPlans()">{{t("resellerPlans.search")}}</button></div><p v-if="planError" class="message error">{{planError}}</p><p v-if="planLoading">{{t("resellerPlans.loading")}}</p><div class="inline-actions"><button v-for="plan in plans" :key="plan.id" class="btn small secondary" :disabled="busy" :aria-pressed="chosen?.id===plan.id" @click="chosen=plan">{{plan.title}} · {{plan.is_active?t('resellerPlans.active'):t('resellerPlans.planInactive')}}</button></div><div class="pager"><button :disabled="planPage<=1||planLoading" @click="planPage--;loadPlans()">‹</button><span>{{faNumber(planPage)}} · {{faNumber(planTotal)}} {{t("resellerPlans.plan")}}</span><button :disabled="planPage>=planPages||planLoading" @click="planPage++;loadPlans()">›</button></div><form class="form-grid" @submit.prevent="create"><fieldset :disabled="busy" class="form-grid"><label class="field"><span>{{t("agreementPrice.method")}}</span><select :aria-label="t('agreementPrice.method')" v-model="newMode" required><option value="" disabled>{{t("resellerPlans.selectOption")}}</option><option value="catalog">{{t("agreementPrice.catalog")}}</option><option value="fixed">{{t("agreementPrice.fixed")}}</option><option value="discount">{{t("agreementPrice.discount")}}</option></select></label><NumField v-if="newMode==='fixed'" v-model="newFixed" :label="t('agreementPrice.fixedAmount')"/><NumField v-if="newMode==='discount'" v-model="newDiscount" :label="t('agreementPrice.discountBps')"/><label class="field"><span>{{t("resellerPlans.roundingMethod")}}</span><select :aria-label="t('resellerPlans.roundingMethod')" v-model="newRounding" required><option value="" disabled>{{t("resellerPlans.selectOption")}}</option><option value="floor">{{t("agreementPrice.floor")}}</option><option value="ceil">{{t("agreementPrice.ceil")}}</option><option value="nearest">{{t("resellerPlans.nearestHalfUp")}}</option></select></label><NumField v-model="newQuantum" :label="t('agreementPrice.increment')"/><label class="field"><span>{{t("resellerPlans.initialStatus")}}</span><select :aria-label="t('resellerPlans.initialStatus')" v-model="newEnabled" required><option value="" disabled>{{t("resellerPlans.selectOption")}}</option><option value="true">{{t("resellerPlans.active")}}</option><option value="false">{{t("resellerPlans.paused")}}</option></select></label><label class="field"><span>{{t("resellerPlans.creationReason")}}</span><input v-model="newReason" minlength="3" maxlength="250" required/></label><button class="btn" :disabled="!chosen||!newMode||!newRounding||!newQuantum||newEnabled===''||newReason.trim().length<3||(newMode==='fixed'&&newFixed==='')||(newMode==='discount'&&newDiscount==='')">{{t("resellerPlans.createAgreement")}}</button></fieldset></form></template></Modal></div></div></template>
<style scoped>fieldset{border:0;padding:0}details{padding:12px 0;border-bottom:1px solid var(--line)}summary{cursor:pointer}</style>
